package com.bank.loan.service;

import com.bank.loan.model.Employee;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class LoanOfferService {
    private static final Logger log = Logger.getLogger(LoanOfferService.class.getName());
    private static final BigDecimal LOW  = new BigDecimal("40000");
    private static final BigDecimal HIGH = new BigDecimal("80000");

    public List<Employee> midBandEmployees(List<Employee> employees) {
        log.info(() -> "Filtering salary in inclusive band [" + LOW + ", " + HIGH + "]");
        return employees.stream()
                // Inclusive: >= LOW AND <= HIGH, using exact BigDecimal comparisons.
                .filter(e -> e.getSalary().compareTo(LOW) >= 0
                          && e.getSalary().compareTo(HIGH) <= 0)
                .collect(Collectors.toList());
    }
}
