package com.bank.loan;

import com.bank.loan.model.Employee;
import com.bank.loan.service.LoanOfferService;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", new BigDecimal("95000")),  // above
            new Employee("Priya",  new BigDecimal("40000")),  // on low boundary
            new Employee("Amit",   new BigDecimal("60000")),  // inside
            new Employee("Neha",   new BigDecimal("80000")),  // on high boundary
            new Employee("Karan",  new BigDecimal("35000"))   // below
        );

        new LoanOfferService().midBandEmployees(staff)
            .forEach(e -> log.info(() -> "Mid-band loan offer: " + e));
    }
}
